SysDataModelXML.SQLUpdateScript:
--LINKADDNEWROWS --LINKAUTOREPLACEEMPTYCOLUMNS DECLARE @NUM INT; DECLARE @DOCSTA VARCHAR;
--SELECT @NUM=ISNULL(MAX(D.DOCLIN),0)+10 --FROM -- [PBOLD] D -- INNER JOIN [PBOLH] H -- ON D.DOCNUM=H.DOCNUM --WHERE D.DOCNUM = N'#DOCNUM#'
SELECT @NUM = Isnull(Max(D.DOCLIN), 0) + 10 ,@DOCSTA = Max(H.DOCSTA) FROM [PBOLH] H LEFT JOIN [PBOLD] D -- 改为LEFT JOIN ON H.DOCNUM = D.DOCNUM WHERE H.DOCNUM = N'#DOCNUM#' -- 查询条件放在主表
MERGE INTO [PBOLD] D USING ( SELECT N'#DOCNUM#' DOCNUM ,IIF(0#DOCLIN#=0,@NUM,0#DOCLIN#) DOCLIN ,N'#FAC#' FAC ,N'#ITMNO#' ITMNO ,N'#ITMVER#' ITMVER ,N'#IVATTYP#' IVATTYP ,N'#REQDAT#' REQDAT ,N'#UOM#' UOM ,IIF('#UOMCOE#'='NaN',1, 0#UOMCOE#) UOMCOE ,N'#STU#' STU ,0#QTY# QTY ,0#QTYSTU# QTYSTU ,IIF('#UOMCOE#'='NaN',1, 0#UOMCOE#) CTRQTY ,0#QTY# CTRNUM ,0#NETPRI# NETPRI ,0#GROPRI# GROPRI ,0#TAXRT# TAXRT ,1.00 * 0#NETPRI#*0#QTYSTU# NETAMT --无税金额 ,0#TAXAMT# TAXAMT ,1.00 * 0#GROPRI#*0#QTYSTU# GRPAMT --含税金额 ,N'#CHAREA#' CHAREA ,N'#REMARK#' REMARK ,N'#SRCTYP#' SRCTYP ,N'#SRCDOC#' SRCDOC ,0#SRCLIN# SRCLIN ,N'#ORITYP#' ORITYP ,N'#ORIDOC#' ORIDOC ,0#ORILIN# ORILIN ,N'#CLOREA#' CLOREA --,N'1' DOCSTA ,@DOCSTA DOCSTA ,N'#CVFCOD#' CVFCOD ,N'#LOGIN_USER#' CREUSR , GETDATE() CRETIM WHERE NOT EXISTS ( -- 增加重复判断：同一DOCNUM下，若SRCDOC和SRCLIN已存在且不是当前自身行，则过滤 SELECT 1 FROM [PBOLD] WHERE DOCNUM = N'#DOCNUM#' AND SRCDOC = N'#SRCDOC#' AND SRCLIN = 0#SRCLIN# AND (0#DOCLIN# = 0 OR DOCLIN != 0#DOCLIN#) -- 排除当前行自身（当DOCLIN非0时） ) ) S ON (S.[DOCNUM] = D.[DOCNUM] AND S.DOCLIN=D.DOCLIN) WHEN MATCHED THEN UPDATE SET FAC = S.FAC ,ITMNO = S.ITMNO ,ITMVER = S.ITMVER ,IVATTYP = S.IVATTYP ,REQDAT = S.REQDAT ,UOM = S.UOM ,UOMCOE = S.UOMCOE ,STU = S.STU ,QTY = S.QTY ,QTYSTU=S.QTYSTU ,CTRQTY=S.CTRQTY ,CTRNUM=S.CTRNUM ,NETPRI = S.NETPRI ,GROPRI = S.GROPRI ,TAXRT = S.TAXRT ,NETAMT = S.NETAMT ,TAXAMT = S.TAXAMT ,GRPAMT = S.GRPAMT ,CHAREA = S.CHAREA ,REMARK = S.REMARK ,SRCTYP = S.SRCTYP ,SRCDOC = S.SRCDOC ,SRCLIN = S.SRCLIN ,ORITYP = S.ORITYP ,ORIDOC = S.ORIDOC ,ORILIN = S.ORILIN ,CLOREA = S.CLOREA ,CVFCOD = S.CVFCOD ,[UPDUSR]='#LOGIN_USER#' ,[UPDTIM]=GETDATE() WHEN NOT MATCHED THEN INSERT ( DOCNUM ,DOCLIN ,FAC ,ITMNO ,ITMVER ,IVATTYP ,REQDAT ,UOM ,UOMCOE ,STU ,QTY ,QTYSTU ,CTRQTY ,CTRNUM ,NETPRI ,GROPRI ,TAXRT ,NETAMT ,TAXAMT ,GRPAMT ,CHAREA ,REMARK ,SRCTYP ,SRCDOC ,SRCLIN ,ORITYP ,ORIDOC ,ORILIN ,DOCSTA ,CLOREA ,CVFCOD ,CREUSR ,CRETIM ) VALUES ( S.DOCNUM ,S.DOCLIN ,S.FAC ,S.ITMNO ,S.ITMVER ,S.IVATTYP ,S.REQDAT ,S.UOM ,S.UOMCOE ,S.STU ,S.QTY ,S.QTYSTU ,S.CTRQTY ,S.CTRNUM ,S.NETPRI ,S.GROPRI ,S.TAXRT ,S.NETAMT ,S.TAXAMT ,S.GRPAMT ,S.CHAREA ,S.REMARK ,S.SRCTYP ,S.SRCDOC ,S.SRCLIN ,S.ORITYP ,S.ORIDOC ,S.ORILIN ,S.DOCSTA ,S.CLOREA ,S.CVFCOD ,S.CREUSR ,S.CRETIM );
